FoamFile
{
    version 2.0;
    format ascii;
    class volVectorField;
    object U;
}

dimensions [0 1 -1 0 0 0 0];
internalField uniform (0 0 0);
boundaryField
{
    drive
    {
        type fixedValue;
        value uniform (0 0 0);
    }
    return
    {
        type fixedValue;
        value uniform (0 0 0);
    }
    shell
    {
        type fixedValue;
        value uniform (0 0 0);
    }
    span
    {
        type empty;
    }
}

FoamFile
{
    version 2.0;
    format ascii;
    class volScalarField;
    object p;
}

dimensions [0 2 -2 0 0 0 0];
internalField uniform 0;
boundaryField
{
    drive
    {
        type fixedValue;
        value uniform 0;
    }
    return
    {
        type fixedValue;
        value uniform 0;
    }
    shell
    {
        type fixedValue;
        value uniform 0;
    }
    span
    {
        type empty;
    }
}

FoamFile
{
    version 2.0;
    format ascii;
    class dictionary;
    object physicalProperties;
}

nu [0 2 -1 0 0 0 0] 0.00001;

FoamFile
{
    version 2.0;
    format ascii;
    class dictionary;
    object blockMeshDict;
}

scale 1;
vertices
(
    (0 0 0)
    (0.037 0 0)
    (0.037 0.023 0)
    (0 0.023 0)
    (0 0 0.001)
    (0.037 0 0.001)
    (0.037 0.023 0.001)
    (0 0.023 0.001)
);
blocks
(
    hex (0 1 2 3 4 5 6 7) (8 6 1) simpleGrading (1 1 1)
);
edges ();
boundary
(
    drive
    {
        type patch;
        faces ((0 4 7 3));
    }
    return
    {
        type patch;
        faces ((1 2 6 5));
    }
    shell
    {
        type wall;
        faces ((0 1 5 4) (3 7 6 2));
    }
    span
    {
        type empty;
        faces ((0 3 2 1) (4 5 6 7));
    }
);
mergePatchPairs ();

FoamFile
{
    version 2.0;
    format ascii;
    class dictionary;
    object controlDict;
}

application icoFoam;
startFrom startTime;
startTime 0;
stopAt endTime;
endTime 0.02;
deltaT 0.01;
writeControl timeStep;
writeInterval 1;

FoamFile
{
    version 2.0;
    format ascii;
    class dictionary;
    object fvSchemes;
}

ddtSchemes { default Euler; }
gradSchemes { default Gauss linear; }
divSchemes { default none; div(phi,U) Gauss upwind; }
laplacianSchemes { default Gauss linear corrected; }
interpolationSchemes { default linear; }
snGradSchemes { default corrected; }

FoamFile
{
    version 2.0;
    format ascii;
    class dictionary;
    object fvSolution;
}

solvers
{
    p { solver PCG; preconditioner DIC; tolerance 1e-06; relTol 0; }
    U { solver smoothSolver; smoother symGaussSeidel; tolerance 1e-06; relTol 0; }
}
PISO { nCorrectors 2; nNonOrthogonalCorrectors 0; }
